import {readFile,writeFile,copyFile,mkdir}from'node:fs/promises';
import{createHash}from'node:crypto';
import{resolve,join}from'node:path';
import{responsePrompt}from'../../../scripts/lean-execution-trials.mjs';
import{readNativeControls}from'../../../scripts/frontend-native-capture.mjs';
const root=resolve('.unlazy/release-447/response'),diagnosis=resolve('.unlazy/release-447/e4-diagnosis');
